@namespace sv_d723c3817c564b849d67c3b10b48abec.Components.Pages.Settings

<nav class="settings-nav">
    <h5 class="settings-nav-title">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link @(section == ActiveSection ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section)">
                    <span class="nav-icon">@GetIcon(section)</span>
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-nav {
    min-width: 220px;
    padding: 1.5rem 1rem;
    border-right: 1px solid #e0e0e0;
    background: #f8f9fa;
    height: 100%;
}

.settings-nav-title {
    font-weight: 600;
    margin-bottom: 1rem;
    padding-left: 0.75rem;
    color: #333;
}

.settings-nav .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 0.75rem;
    border-radius: 6px;
    color: #555;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
}

.settings-nav .nav-link:hover {
    background: #e9ecef;
    color: #333;
}

.settings-nav .nav-link.active {
    background: #0d6efd;
    color: white;
    font-weight: 500;
}

.nav-icon {
    font-size: 1.1rem;
}

@namespace sv_d723c3817c564b849d67c3b10b48abec.Components.Pages.Settings
@using sv_d723c3817c564b849d67c3b10b48abec.Services

<div class="profile-section">
    <h4>Profile</h4>

    @if (SuccessMessage is not null)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @SuccessMessage
            <button type="button" class="btn-close" @onclick="() => SuccessMessage = null"></button>
        </div>
    }

    <div class="profile-form">
        <div class="avatar-area mb-4">
            <img src="@AvatarUrl" alt="Avatar" class="avatar-preview" />
            <div class="mt-2">
                <label class="form-label">Avatar URL</label>
                <input type="text" class="form-control" @bind="AvatarUrl" />
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="DisplayName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="Email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="Bio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName { get; set; } = "";
    private string Email { get; set; } = "";
    private string AvatarUrl { get; set; } = "";
    private string Bio { get; set; } = "";
    private string? SuccessMessage { get; set; }

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_initialized)
        {
            LoadFromProfile(Profile);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile(UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        AvatarUrl = profile.AvatarUrl;
        Bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        SuccessMessage = "Profile saved successfully!";
    }

    private void Discard()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
        SuccessMessage = null;
    }
}

.profile-section h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.avatar-area {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.avatar-preview {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
    background: #f0f0f0;
}

.profile-form {
    max-width: 500px;
}

