@using sv_d723c3817c564b849d67c3b10b48abec.Services

<div class="appearance-section">
    <h4>Appearance</h4>

    <div class="row">
        <div class="col-md-6">
            <!-- Theme -->
            <div class="mb-4">
                <h6>Theme</h6>
                @foreach (var theme in Themes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(SelectedTheme == theme)"
                               @onchange="() => SelectedTheme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <h6>Font Size</h6>
                @foreach (var size in FontSizes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(SelectedFontSize == size)"
                               @onchange="() => SelectedFontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <!-- Language -->
            <div class="mb-4">
                <h6>Language</h6>
                <select class="form-select" style="max-width: 250px;" @bind="SelectedLanguage">
                    @foreach (var lang in Languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
        </div>

        <!-- Live Preview -->
        <div class="col-md-6">
            <h6>Preview</h6>
            <div class="preview-area @PreviewThemeClass" style="font-size: @PreviewFontSize;">
                <div class="preview-header">
                    <strong>Sample Header</strong>
                </div>
                <div class="preview-content @(CompactMode ? "compact" : "")">
                    <p>This is how your content will look with the selected settings.</p>
                    <p class="text-muted">Theme: @SelectedTheme | Font: @SelectedFontSize | Language: @SelectedLanguage</p>
                    <button class="btn btn-sm btn-primary">Sample Button</button>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string SelectedTheme { get; set; } = "Light";
    private string SelectedFontSize { get; set; } = "Medium";
    private string SelectedLanguage { get; set; } = "English";
    private bool CompactMode { get; set; }

    private static readonly string[] Themes = { "Light", "Dark", "System" };
    private static readonly string[] FontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] Languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            SelectedTheme = Settings.Theme;
            SelectedFontSize = Settings.FontSize;
            SelectedLanguage = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string PreviewThemeClass => SelectedTheme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string PreviewFontSize => SelectedFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await OnSave.InvokeAsync(updated);
    }
}
